import 'package:bloc/bloc.dart';import 'package:flutter/material.dart';import '../../../../../Config/Routes/route_name.dart';import '../../../../../main.dart';import '../../data/entities/register_model.dart';import '../../data/entities/user_data_model.dart';import '../../data/entities/login_model.dart';import '../../domain/repository/authentication_repo_impl.dart';part 'authentication_state.dart';class AuthenticationCubit extends Cubit<AuthenticationState> {  AuthenticationCubit(this.authenticationRepoImpl)      : super(AuthenticationInitial());  final AuthenticationRepoImpl authenticationRepoImpl;  Future<void> loginByEmail(LoginModel loginModel) async {    emit(AuthenticationLoginLoading());    final response = await authenticationRepoImpl.loginByEmail(      loginModel,    );    response.fold((failure) {      emit(AuthenticationLoginError(message: failure.errMessage));    }, (data) async {      emit(AuthenticationLoginSuccess(data: data));      await kNavigationService.clearAndNavigateTo(AppRoutes.main);    });  }  Future<void> createAccount(RegisterModel registerModel) async {    emit(AuthenticationCreateAccountLoading());    final response = await authenticationRepoImpl.registerByGoogle( registerModel);    response.fold((failure) {      emit(AuthenticationCreateAccountError(message: failure.errMessage));    }, (data) {      emit(AuthenticationCreateAccountSuccess());    });  }}